#include <bits/stdc++.h>
using namespace std;

#define ll long long

static inline ll strength(const vector<ll> &S, int n, int c1, int c2) {
    int p1 = c1;
    int p2 = c1 + 2 * c2;
    int p3 = 3 * n - 2 * c1 - c2;
    return 2LL * S[p1] + S[p2] + 3LL * S[p3];
}

void solve() {
    int n;
    cin >> n;
    int total = 3 * n;
    vector<ll> a(total);
    for (int i = 0; i < total; ++i) cin >> a[i];
    sort(a.begin(), a.end(), greater<ll>());
    
    vector<ll> S(total + 1, 0);
    for (int i = 0; i < total; ++i) S[i + 1] = S[i] + a[i];
    
    ll max_str = 0;
    for (int c1 = 0; c1 <= n; ++c1) {
        int low = 0, high = n - c1;
        while (high - low > 3) {
            int m1 = low + (high - low) / 3;
            int m2 = high - (high - low) / 3;
            if (strength(S, n, c1, m1) < strength(S, n, c1, m2))
                low = m1;
            else high = m2;
        }
        for (int c2 = low; c2 <= high; ++c2)
            max_str = max(max_str, strength(S, n, c1, c2));
    }
    cout << max_str << '\n';
}
int main() {
	// your code goes here
	cin.tie(0)->sync_with_stdio(0);
	int t;
	cin >> t;
	while (t--) solve();
	return 0;

}
